_url":"https://warburgpincus.com/2024/04/10/warburg-pincus-invests-in-appasamy-associates-the-largest-indian-brand-for-ophthalmic-equipment-and-intraocular-lenses/","evidence":"Mumbai, Chennai, April 10, 2024: Appasamy Associates Pvt. Ltd. (“Appasamy” or “the Company”), a leading Indian manufacturer of ophthalmic equipment and devices in India, announced today that Warburg Pincus, a leading global growth investor has acquired a stake in the Company.","verified":null},{"key":"pr:6dc067c790d1556ac6cf12c16476dad1","date":"2024-02-26","date_text":null,"kind":"other","asset_class":"private_equity","target":"Weave Living","portco_name":"Weave Living","target_website":"weavecoliving.com","investor":"Warburg Pincus","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":["Sachin Doshi (founder)"],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Weave Living secures further investment from Warburg Pincus to accelerate expansion throughout Asia-Pacific","summary":"Weave Living secured a further equity injection from existing shareholders Warburg Pincus and its founder Sachin Doshi; the amount is not stated.","source_name":"Warburg Pincus","source_url":"https://warburgpincus.com/2024/02/26/weave-living-secures-further-investment-from-warburg-pincus-to-accelerate-expansion-throughout-asia-pacific/","evidence":"HONG KONG, Feb 26, 2024 – Weave Living (“Weave”), Asia-Pacific’s pre-eminent living sector specialist, announced today that it has secured further investment from its existing shareholders – Warburg Pincus, a leading global growth investor and the Founder – Sachin Doshi.","verified":null},{"key":"pr:7c49b55a00065c4bc750f356ce116574","date":"2024-02-08","date_text":null,"kind":"other","asset_class":"private_equity","target":"Bloomerang","portco_name":"Bloomerang","target_website":"bloomerang.co","investor":"Warburg Pincus","sponsor_is_investor":true,"sponsor_rol