tions.baxter.com","investor":"Advent International","sponsor_is_investor":false,"sponsor_role":"co_investor","co_investors":["Warburg Pincus"],"seller":"Baxter International Inc.","round":null,"stake_pct":null,"amount":4250000000.0,"currency":"USD","amount_basis":"unspecified","valuation":null,"valuation_currency":null,"headline":"Advent International and Warburg Pincus Complete Acquisition of Baxter’s BioPharma Solutions Business","summary":"Advent International and Warburg Pincus completed their purchase of Baxter's BioPharma Solutions CDMO business, renamed Simtra BioPharma Solutions.","source_name":"Warburg Pincus","source_url":"https://warburgpincus.com/2023/10/02/advent-international-and-warburg-pincus-complete-acquisition-of-baxters-biopharma-solutions-business/","evidence":"Under the terms of the definitive agreement, Baxter received $4.25 billion in cash, subject to certain closing adjustments.","verified":true},{"key":"pr:97931e4436c3278b874922219e20b922","date":"2023-09-28","date_text":null,"kind":"funding_round","asset_class":"venture_capital","target":"Nord Security","portco_name":"Nord Security","target_website":"nordsecurity.com","investor":"Warburg Pincus","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":["Novator Ventures","Burda Principal Investments"],"seller":null,"round":"growth","stake_pct":null,"amount":100000000.0,"currency":"USD","amount_basis":"round_size","valuation":3000000000.0,"valuation_currency":"USD","headline":"Nord Security Raised Another $100M Investment Round","summary":"Nord Security raised a $100 million round from Warburg Pincus with existing investors Novator Ventures and Burda Principal Investments, doubling its valuation to $3 billion.","source_name":"Warburg Pincus","source_url":"https://warburgpincus.com/2023/09/28/nord-security-raised-another-100m-investment-round/","evidence":"Nord Security, a global leader in internet privacy and security solutions, announced a $100M financing round from Warburg Pincus, a leading global growth investor.","verified":true},{"key":"pr:45ae03eb44d3858873d5088e0f635a9f","date":"2023-09-07","date_text":null,"kind":"other","asset_class":"private_equity","target":"Prismic Life Reinsurance, Ltd.","portco_name":null,"target_website":"prismicre.com","investor":"Prudential Financial, Inc.","sponsor_is_investor":false,"sponsor_role":"co_investor","co_investors":["Warburg Pincus","A group of global investors"],"seller":null,"round":null,"stake_pct":15.0,"amount":1000000000.0,"currency":"USD","amount_basis":"round_size","valuation":null,"valuation_currency":null,"headline":"Prudential Financial, Inc. and Warburg Pincus announce launch of Prismic Life Re","summary":"Prudential and Warburg Pincus launched Bermuda life and annuity reinsurer Prismic with $1 billion of initial equity from them and other investors; Warburg Pincus initially owns 15%.","source_name":"Warburg Pincus","source_url":"https://warburgpincus.com/2023/09/07/prudential-financial-inc-and-warburg-pincus-announce-launch-of-prismic-life-re/","evidence":"A group of global investors has agreed to make equity investments in Prismic, alongside Prudential and Warburg Pincus, giving Prismic a combined initial equity investment of $1 billion.","verified":true},{"key":"pr:cf61cea51b2d5816312d2ffb44017bd2","date":"2023-09-01","date_text":null,"kind":"company_exit","asset_class":"private_equity","target":"Reiss","portco_name":"Reiss","target_website":"reiss.com","investor":"NEXT plc","sponsor_is_investor":false,"sponsor_role":"seller","co_investors":["Reiss family"],"seller":"Warburg Pincus","round":null,"stake_pct":34.0,"amount":128000000.0,"currency":"GBP","amount_basis":"stake_price","valuation":null,"valuation_currency":null,"headline":"Acquisition of Warburg Pincus’ Interest in Reiss","summary":"NEXT and the Reiss family agreed to buy Warburg Pincus's entire 34% interest in fashion retailer Reiss for £128 million.","source_name":"Warburg Pincus","source_url":"https://warburgpincus.com/2023/09/01/acquisition-of-warburg-pincus-interest-in-reiss/","evidence":"NEXT plc (“NEXT”) announces that it has agreed1 the terms of a transaction whereby NEXT and the Reiss family will acquire the entirety of Warburg Pincus’ (“WP”) 34% interest in the Reiss Group (“Reiss”) for total consideration of £128m on a fully diluted basis.","verified":true},{"key":"pr:67aa89de015d509128067c28f5750bc1","date":"2023-08-09","date_text":null,"kind":"company_acquisition","asset_class":"private_equity","target":"Epassi Group","portco_name":"Epassi","target_website":"epassi.com","investor":"TA Associates","sponsor_is_investor":false,"sponsor_role":"co_investor","co_investors":["Warburg Pincus"],"seller":"Bregal Milestone","round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"TA and Warburg Pincus acquire majority stake in Epassi Group from Bregal Milestone","summary":"TA Associates and Warburg Pincus acquired a majority stake in Nordic employee benefits platform Epassi from Bregal Milestone.","source_name":"Warburg Pincus","source_url":"https://warburgpincus.com/2023/08/09/ta-and-warburg-pincus-acquire-majority-stake-in-epassi-group-from-bregal-milestone/","evidence":"9 Aug 2023 - Funds advised by TA Associates (”TA”) and Warburg Pincus LLC (“Warburg Pincus”), two leading global private equity firms focused on growth investing, have acquired a majority stake in Epassi Group (”Epassi” or \"the Company”) from majority shareholder Bregal Milestone, a leading technology growth private equity firm.","verified":null},{"key":"pr:ec235509fb7fb286e1fa8099e915eeb3","date":"2023-07-25","date_text":null,"kind":"minority_investment","asset_class":"private_equity","target":"Banc of California","portco_name":"Banc of California","target_website":"bancofcal.com","investor":"funds managed by Warburg Pincus LLC","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":["Centerbridge Partners"],"seller":nul