l growth investor.","verified":true},{"key":"pr:9b918f839397f4e3bd2e586ccb19b7e8","date":"2021-06-02","date_text":null,"kind":"minority_investment","asset_class":"private_equity","target":"Global Healthcare Exchange (GHX)","portco_name":"Global Healthcare Exchange","target_website":"ghx.com","investor":"Warburg Pincus","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":["Temasek (remains majority)"],"seller":"Thoma Bravo","round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Global Healthcare Exchange Announces Minority Investment by Warburg Pincus to Fuel Strategic Initiatives and Growth Opportunities","summary":"GHX agreed a minority investment from Warburg Pincus as Thoma Bravo exited; Temasek remains majority owner. Terms not disclosed.","source_name":"Warburg Pincus","source_url":"https://warburgpincus.com/2021/06/02/global-healthcare-exchange-announces-minority-investment-by-warburg-pincus-to-fuel-strategic-initiatives-and-growth-opportunities/","evidence":"Louisville, CO - Wednesday, June 2, 2021 - Global Healthcare Exchange (GHX), operator of the industry’s largest cloud-based trading network that connects those who buy, sell and use products needed to deliver patient care, today announced it has entered into a definitive agreement to receive a strategic investment from Warburg Pincus, a leading global growth investor.","verified":null},{"key":"pr:2b9df3e35433384a1042a33482285c8f","date":"2021-06-02","date_text":null,"kind":"other","asset_class":"private_equity","target":"NEOGOV","portco_name":"NEOGOV","target_website":"neogov.com","investor":"The Carlyle Group (Carlyle Partners VII)","sponsor_is_investor":false,"sponsor_role":"co_investor","co_investors":["Warburg Pincus (existing investor)"],"seller":null,"round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"NEOGOV Announces Growt