null,"amount":8900000000.0,"currency":"USD","amount_basis":"enterprise_value","valuation":null,"valuation_currency":null,"headline":"VillageMD’s $8.9bn Acquisition of Summit Health","summary":"VillageMD agreed to acquire Warburg Pincus-backed Summit Health-CityMD in a deal valued at $8.9 billion, with Warburg Pincus keeping an equity interest in the combination.","source_name":"MergerSight Group","source_url":"https://www.mergersight.com/post/villagemd-s-8-9bn-acquisition-of-summit-health","evidence":"VillageMD is set to acquire Summit Health in a deal valued at $8.9bn and expected to close in the first quarter of 2023.","verified":true},{"key":"pr:3029ebc7ba59b633baa4a299088196ed","date":"2019-12-16","date_text":null,"kind":"secondary","asset_class":"private_equity","target":"Allied Universal","portco_name":"Allied Universal","target_website":"aus.com","investor":"Caisse de dépôt et placement du Québec (CDPQ)","sponsor_is_investor":false,"sponsor_role":"co_investor","co_investors":["Investment group led by Warburg Pincus and an affiliate of the J. Safra Group"],"seller":"Wendel SE (79% of its investment)","round":null,"stake_pct":null,"amount":null,"currency":null,"amount_basis":null,"valuation":null,"valuation_currency":null,"headline":"Allied Universal Holder Completes Sale","summary":"Wendel completed the sale of most of its Allied Universal stake to CDPQ and a group led by Warburg Pincus and a J. Safra affiliate, for net cash proceeds of $721 million.","source_name":"Orange County Business Journal","source_url":"https://www.ocbj.com/services/allied-universal-shareholder-completes-sale/","evidence":"It sold the stake to Caisse de dépôt et placement du Québec (CDPQ), Canada’s second largest pension fund, and a new investment group led by Warburg Pincus and an affiliate of the J. Safra Group.","verified":null},{"key":"pr:8eaf21c017d0365ccaa7bda3c1378e1d","date":"2023-03-27","date_text":null,"kind":"secondary","asset_class":"private_equity","target":"Kalyan Jewellers","portco_name":"Kalyan Jewellers India Limited","target_website":"kalyanjewellers.net","investor":"Block deal buyers","sponsor_is_investor":false,"sponsor_role":"seller","co_investors":[],"seller":"Warburg Pincus","round":null,"stake_pct":2.5,"amount":2880000000.0,"currency":"INR","amount_basis":"stake_price","valuation":null,"valuation_currency":null,"headline":"Kalyan Jewellers block deal to see 2.5% stake of Warburg Pincus changing hands","summary":"Warburg Pincus was set to sell a 2.5% stake in listed Kalyan Jewellers in a block deal at Rs 110 a share (about Rs 288 crore).","source_name":"Moneycontrol","source_url":"https://www.moneycontrol.com/news/business/warburg-pincus-to-sell-2-5-stake-in-kalyan-jewellers-through-block-deal-sources-10321681.html","evidence":"The shares would be offloaded at Rs 110 apiece, taking the overall deal value to Rs 288 crore, the persons privy to the development told CNBC TV-18.","verified":true},{"key":"pr:445647d678968f98b215b10c47186181","date":"2024-08-22","date_text":null,"kind":"company_exit","asset_class":"private_equity","target":"Kalyan Jewellers","portco_name":"Kalyan Jewellers India Limited","target_website":"kalyanjewellers.net","investor":"T.S. Kalyanaraman (promoter)","sponsor_is_investor":false,"sponsor_role":"seller","co_investors":["Public market institutional investors"],"seller":"Highdell Investment (Warburg Pincus)","round":null,"stake_pct":2.36,"amount":13000000000.0,"currency":"INR","amount_basis":"stake_price","valuation":null,"valuation_currency":null,"headline":"Warburg Pincus exits Kalyan Jewellers, promoter picks up 2.36% stake","summary":"Warburg Pincus completed its exit from Kalyan Jewellers, selling 2.36% to the promoter for Rs 1,300 crore and 6.81% to institutional investors.","source_name":"Moneycontrol","source_url":"https://www.moneycontrol.com/news/business/markets/warburg-pincus-exits-kalyan-jewellers-promoter-buys-stake-12804346.html","evidence":"In a regulatory filing on August 21, the company had informed the stock exchanges that a Warburg Pincus entity - Highdell Investment - will be selling 2.36 percent stake in Kalyan Jewellers to Kalyanaraman for Rs 1,300 crore, at Rs 535 each.","verified":true},{"key":"pr:a167c16e9642724de841de83a63db4cc","date":"2017-09-11","date_text":null,"kind":"funding_round","asset_class":"venture_capital","target":"Ecom Express","portco_name":"Ecom Express Limited","target_website":"ecomexpress.in","investor":"Eaglebay Investment (Warburg Pincus)","sponsor_is_investor":true,"sponsor_role":"investor","co_investors":[],"seller":null,"round":null,"stake_pct":null,"amount":1920000000.0,"currency":"INR","amount_basis":"round_size","valuation":null,"valuation_currency":null,"headline":"Ecom Express secures investment of Rs 192 crore from Warburg Pincus: Report","summary":"Indian e-commerce logistics firm Ecom Express raised Rs 192 crore from existing investor Warburg Pincus, as reported by The Economic Times.","source_name":"MediaNama","source_url":"https://www.medianama.com/2017/09/223-175294-2/","evidence":"E-commerce logistics solutions provider Ecom Express has raised Rs 192 crore from its existing investor Warburg Pincus, reports The Economic Times.","verified":true}]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'Warburg Pincus'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'Warburg Pincus'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'warburgpincus.com: /warburg-pincus-portfolio/ (full list of all historical and current portfolio companies as of 6/30/2026, 1,119 entries) merged with /investments/ (182 active investments as of June 2026, each detail page read for sector, year, website, description); enriched and extended from the firm''s own news releases (post-sitemap1/2.xml, 637 posts) for investment years, exits and July-Sept ', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'Warburg Pincus', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
